void sink(std::string& s);
void sink(std::string&& s);

// Perfect Forwarding Wrapper Template
template <typename T>
void wrapper(T&& arg) {
    // std::forward<T> conditionally casts to preserve category
    sink(std::forward<T>(arg));
}

/* Compiler Implications: Reference Collapsing Rules */
// 1. Lvalue input: T is deduced as std::string&
//    T&& collapses to std::string& (lvalue reference)
//    std::forward<std::string&> returns std::string&

// 2. Rvalue input: T is deduced as std::string
//    T&& remains std::string&& (rvalue reference)
//    std::forward<std::string> returns std::string&&
// Note: Requires T&& (Universal Reference) used in template context.
